#include <stdlib.h>
#include <string.h>

#define DOCUMENT_EDIT_TEXT_ATTRIBUTE_LIMIT 128U

static bool text_fragment_append(uint8_t *output, size_t capacity, size_t *used,
    const uint8_t *bytes, size_t length)
{
    if (output == NULL || used == NULL || (length > 0U && bytes == NULL) ||
        *used > capacity || length > capacity - *used) return false;
    if (length > 0U) memcpy(output + *used, bytes, length);
    *used += length;
    return true;
}

document_edit_error document_edit_insert_text_element(document_edit *edit,
    document_handle parent, const document_edit_template_attribute *attributes,
    size_t attribute_count, base_bytes text, document_handle *out_inserted)
{
    if (edit == NULL || out_inserted == NULL || !base_bytes_valid(text) ||
        (attribute_count > 0U && attributes == NULL))
        return DOCUMENT_EDIT_INVALID_ARGUMENT;
    if (attribute_count > DOCUMENT_EDIT_TEXT_ATTRIBUTE_LIMIT)
        return DOCUMENT_EDIT_LIMIT;
    uint8_t *fragment = malloc(DOCUMENT_EDIT_XML_FRAGMENT_LIMIT);
    if (fragment == NULL) return DOCUMENT_EDIT_OUT_OF_MEMORY;
    size_t used = 0U;
    static const uint8_t start[] = "<text";
    bool okay = text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
        &used, start, sizeof(start) - 1U);
    for (size_t index = 0U; okay && index < attribute_count; ++index) {
        base_bytes name = attributes[index].name;
        base_bytes value = attributes[index].value;
        if (!document_edit_name_valid(name) || !base_bytes_valid(value)) {
            free(fragment);
            return DOCUMENT_EDIT_INVALID_NAME;
        }
        for (size_t prior = 0U; prior < index; ++prior) {
            if (attributes[prior].name.len == name.len &&
                memcmp(attributes[prior].name.ptr, name.ptr, name.len) == 0) {
                free(fragment);
                return DOCUMENT_EDIT_DUPLICATE_ATTRIBUTE;
            }
        }
        uint8_t *encoded = NULL;
        size_t encoded_length = 0U;
        if (!document_edit_encode_attribute(value, '"', &encoded, &encoded_length)) {
            free(fragment);
            return DOCUMENT_EDIT_OUT_OF_MEMORY;
        }
        static const uint8_t equals[] = "=\"";
        static const uint8_t quote[] = "\"";
        okay = text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
                &used, (const uint8_t *)" ", 1U) &&
            text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
                &used, name.ptr, name.len) &&
            text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
                &used, equals, sizeof(equals) - 1U) &&
            text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
                &used, encoded, encoded_length) &&
            text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
                &used, quote, sizeof(quote) - 1U);
        free(encoded);
    }
    static const uint8_t open_end[] = ">";
    static const uint8_t close[] = "</text>";
    uint8_t *encoded_text = NULL;
    size_t encoded_text_length = 0U;
    if (okay && !document_edit_encode_text(text, &encoded_text,
            &encoded_text_length)) okay = false;
    if (okay) okay = text_fragment_append(fragment,
            DOCUMENT_EDIT_XML_FRAGMENT_LIMIT, &used, open_end, 1U) &&
        text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
            &used, encoded_text, encoded_text_length) &&
        text_fragment_append(fragment, DOCUMENT_EDIT_XML_FRAGMENT_LIMIT,
            &used, close, sizeof(close) - 1U);
    free(encoded_text);
    if (!okay) {
        free(fragment);
        return DOCUMENT_EDIT_LIMIT;
    }
    document_edit_error result = document_edit_insert_xml_fragment(edit, parent,
        (base_bytes){fragment, used}, out_inserted);
    free(fragment);
    if (result == DOCUMENT_EDIT_OK)
        document_edit_history_relabel_latest(edit, DOCUMENT_EDIT_HISTORY_ACTION_ADD_TEXT);
    return result;
}

use std::sync::Arc;
use vexel_document::{parse_owned_document, DocumentParseError, OwnedDocumentModel,
    OwnedParseError};
use vexel_xml::{XmlDiagnostic, XmlError};
use vexel_xml::{tokenize_with_capacity, XmlLimits, XmlToken};

pub const DEFAULT_SOURCE_BYTES: usize = 16 * 1024 * 1024;
pub const DEFAULT_HISTORY_COMMANDS: usize = 1_000;
pub const DEFAULT_HISTORY_BYTES: usize = 64 * 1024 * 1024;
pub const MAX_HISTORY_COMMANDS: usize = 300_000;
pub const MAX_HISTORY_BYTES: usize = 1024 * 1024 * 1024;
pub const MAX_PIECES: usize = 1_000_000;
pub const MAX_FRAGMENT_BYTES: usize = 64 * 1024;
pub const MAX_GROUP_NODES: usize = 128;
pub const HISTORY_LABEL_CAPACITY: usize = 64;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum EditError {
    Ok, InvalidArgument, StaleHandle, NotFound, DuplicateAttribute, DuplicateId,
    InvalidName, MalformedXml, RootDelete, InvalidOperation, Limit, HistoryLimit,
    OutOfMemory, SaveFailed,
}

impl EditError {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Ok => "ok", Self::InvalidArgument => "invalid_argument",
            Self::StaleHandle => "stale_handle", Self::NotFound => "not_found",
            Self::DuplicateAttribute => "duplicate_attribute", Self::DuplicateId => "duplicate_id",
            Self::InvalidName => "invalid_name", Self::MalformedXml => "malformed_xml",
            Self::RootDelete => "root_delete", Self::InvalidOperation => "invalid_operation",
            Self::Limit => "limit", Self::HistoryLimit => "history_limit",
            Self::OutOfMemory => "out_of_memory", Self::SaveFailed => "save_failed",
        }
    }
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct EditLimits { pub history_commands: usize, pub history_bytes: usize }
impl Default for EditLimits {
    fn default() -> Self { Self { history_commands: DEFAULT_HISTORY_COMMANDS, history_bytes: DEFAULT_HISTORY_BYTES } }
}

#[derive(Debug)]
pub struct EditResult { pub error: EditError, pub diagnostic: XmlDiagnostic, pub editor: Option<Editor> }

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct SaveResult {
    pub error: EditError,
    pub source_error: vexel_document_io::SourceSaveError,
    pub diagnostic: XmlDiagnostic,
    pub renamed: bool,
    pub file_synced: bool,
    pub directory_synced: bool,
}

#[derive(Clone, Debug)]
pub(crate) struct Piece { pub(crate) data: Arc<Vec<u8>>, pub(crate) start: usize, pub(crate) len: usize }
impl Piece {
    fn slice(&self, start: usize, len: usize) -> Option<Self> {
        let end = start.checked_add(len)?;
        if end > self.len { return None; }
        Some(Self { data: Arc::clone(&self.data), start: self.start.checked_add(start)?, len })
    }
}

#[derive(Clone, Debug)]
pub(crate) struct Command {
    pub(crate) offset: usize, pub(crate) removed: Vec<Piece>, pub(crate) inserted: Vec<Piece>,
    pub(crate) before_state: u64, pub(crate) after_state: u64, pub(crate) label: String,
    pub(crate) target_slot: u32, pub(crate) coalescible: bool,
}

#[derive(Debug)]
pub struct Editor {
    pub(crate) original: Arc<Vec<u8>>,
    pub(crate) pieces: Vec<Piece>,
    pub(crate) byte_len: usize,
    pub(crate) limits: EditLimits,
    pub(crate) history: Vec<Command>,
    pub(crate) cursor: usize,
    pub(crate) history_bytes: usize,
    pub(crate) state_id: u64,
    pub(crate) saved_state: u64,
    pub(crate) next_state: u64,
    pub(crate) model: OwnedDocumentModel,
    pub(crate) tokens: Vec<XmlToken>,
    pub(crate) cached_source: Arc<Vec<u8>>,
    pub(crate) diagnostic: XmlDiagnostic,
    pub(crate) next_auto_id: u64,
}

impl Editor {
    /// Creates an editor by borrowing and cloning the caller's Arc. The owner
    /// held by this editor keeps the original input alive after return.
    pub fn create(source: &Arc<Vec<u8>>, mut limits: EditLimits) -> EditResult {
        let fail = |error, diagnostic| EditResult { error, diagnostic, editor: None };
        if source.len() > DEFAULT_SOURCE_BYTES {
            return fail(EditError::Limit, XmlDiagnostic { category: XmlError::InputLimit, offset: 0 });
        }
        if limits.history_commands == 0 { limits.history_commands = DEFAULT_HISTORY_COMMANDS; }
        if limits.history_bytes == 0 { limits.history_bytes = DEFAULT_HISTORY_BYTES; }
        if limits.history_commands > MAX_HISTORY_COMMANDS || limits.history_bytes > MAX_HISTORY_BYTES {
            return fail(EditError::Limit, XmlDiagnostic::default());
        }
        let owner = Arc::clone(source);
        let model = match parse_owned_document(&owner) {
            Ok(model) => model,
            Err(error) => { let (edit_error, diagnostic) = map_parse_error(error); return fail(edit_error, diagnostic); }
        };
        let tokens = match parse_tokens(&owner) { Ok(tokens) => tokens, Err((error, diagnostic)) => return fail(error, diagnostic) };
        let mut pieces = Vec::new();
        if !owner.is_empty() {
            if pieces.try_reserve_exact(1).is_err() { return fail(EditError::OutOfMemory, XmlDiagnostic::default()); }
            pieces.push(Piece { data: Arc::clone(&owner), start: 0, len: owner.len() });
        }
        EditResult { error: EditError::Ok, diagnostic: XmlDiagnostic::default(), editor: Some(Self {
            original: Arc::clone(&owner), pieces, byte_len: owner.len(), limits, history: Vec::new(),
            cursor: 0, history_bytes: 0, state_id: 1, saved_state: 1, next_state: 2,
            model, tokens, cached_source: owner, diagnostic: XmlDiagnostic::default(), next_auto_id: 1,
        }) }
    }

    pub fn model(&self) -> &OwnedDocumentModel { &self.model }
    pub fn byte_length(&self) -> usize { self.byte_len }
    pub fn is_dirty(&self) -> bool { self.state_id != self.saved_state }
    pub fn mark_saved(&mut self) { self.saved_state = self.state_id; }
    pub fn mark_unsaved(&mut self) { self.saved_state = 0; }
    pub fn history_count(&self) -> usize { self.history.len() }
    pub fn history_cursor(&self) -> usize { self.cursor }
    pub fn history_bytes(&self) -> usize { self.history_bytes }
    pub fn parse_diagnostic(&self) -> XmlDiagnostic { self.diagnostic }
    pub fn original_source(&self) -> &[u8] { &self.original }

    pub fn save_as(&mut self, path: &[u8], hooks: Option<&mut dyn vexel_document_io::SourceSaveHooks>) -> SaveResult {
        let result = vexel_document_io::source_save_noop(self.cached_source.as_slice(), path,
            64 * 1024 * 1024 / std::mem::size_of::<XmlToken>(), hooks);
        let summary = SaveResult { error: match result.error {
            vexel_document_io::SourceSaveError::Ok => EditError::Ok,
            _ => EditError::SaveFailed,
        }, source_error: result.error, diagnostic: result.parse_diagnostic,
            renamed: result.file_result.renamed, file_synced: result.file_result.file_synced,
            directory_synced: result.file_result.directory_synced };
        if summary.renamed { self.mark_saved(); }
        summary
    }

    pub fn materialize(&self, output: &mut [u8]) -> Result<usize, EditError> {
        if output.len() < self.byte_len { return Err(EditError::InvalidArgument); }
        let mut used = 0usize;
        for piece in &self.pieces {
            let end = piece.start.checked_add(piece.len).ok_or(EditError::Limit)?;
            let data = piece.data.get(piece.start..end).ok_or(EditError::InvalidOperation)?;
            let target_end = used.checked_add(data.len()).ok_or(EditError::Limit)?;
            output.get_mut(used..target_end).ok_or(EditError::InvalidArgument)?.copy_from_slice(data);
            used = target_end;
        }
        if used != self.byte_len { return Err(EditError::InvalidOperation); }
        Ok(used)
    }

    /// Prepare, validate, and atomically publish a source replacement. The new
    /// materialized Arc becomes the model cache, so parsing is done once for
    /// this source state and no edit/query reparses it later.
    pub(crate) fn replace(&mut self, offset: usize, remove_len: usize, insert: &[u8], label: &str,
        target_slot: u32, coalescible: bool) -> Result<(), EditError> {
        let end = offset.checked_add(remove_len).ok_or(EditError::InvalidArgument)?;
        if end > self.byte_len { return Err(EditError::InvalidArgument); }
        if remove_len == insert.len() && self.cached_source.get(offset..end) == Some(insert) { return Ok(()); }
        let new_len = self.byte_len.checked_sub(remove_len).and_then(|n| n.checked_add(insert.len())).ok_or(EditError::Limit)?;
        if new_len > DEFAULT_SOURCE_BYTES { return Err(EditError::Limit); }
        if self.next_state == u64::MAX { return Err(EditError::Limit); }
        let mut before = Vec::new();
        let mut after = Vec::new();
        let mut cursor = 0usize;
        before.try_reserve(4).map_err(|_| EditError::OutOfMemory)?;
        after.try_reserve(4).map_err(|_| EditError::OutOfMemory)?;
        let mut removed_bytes = Vec::new();
        let mut insert_bytes = Vec::new();
        insert_bytes.try_reserve_exact(insert.len()).map_err(|_| EditError::OutOfMemory)?;
        insert_bytes.extend_from_slice(insert);
        let insert_owner = Arc::new(insert_bytes);
        let mut removed_charge = 0usize;
        for piece in &self.pieces {
            let piece_end = cursor.checked_add(piece.len).ok_or(EditError::Limit)?;
            if cursor < offset {
                let keep = offset.min(piece_end) - cursor;
                if keep > 0 { before.push(piece.slice(0, keep).ok_or(EditError::InvalidOperation)?); }
            }
            let overlap_start = cursor.max(offset);
            let overlap_end = piece_end.min(end);
            if overlap_start < overlap_end {
                let relative = overlap_start - cursor;
                let amount = overlap_end - overlap_start;
                removed_charge = removed_charge.checked_add(amount).ok_or(EditError::Limit)?;
                removed_bytes.try_reserve(amount).map_err(|_| EditError::OutOfMemory)?;
                removed_bytes.extend_from_slice(piece.data.get(piece.start + relative..piece.start + relative + amount).ok_or(EditError::InvalidOperation)?);
            }
            if piece_end > end {
                let suffix_at = end.saturating_sub(cursor).min(piece.len);
                if suffix_at < piece.len { after.push(piece.slice(suffix_at, piece.len - suffix_at).ok_or(EditError::InvalidOperation)?); }
            }
            cursor = piece_end;
        }
        if cursor < offset || end > cursor { return Err(EditError::InvalidArgument); }
        let inserted = if insert.is_empty() { Vec::new() } else { vec![Piece { data: insert_owner, start: 0, len: insert.len() }] };
        let mut proposed = Vec::new();
        let count = before.len().checked_add(inserted.len()).and_then(|n| n.checked_add(after.len())).ok_or(EditError::Limit)?;
        if count > MAX_PIECES { return Err(EditError::Limit); }
        proposed.try_reserve_exact(count).map_err(|_| EditError::OutOfMemory)?;
        proposed.extend(before.iter().cloned());
        proposed.extend(inserted.iter().cloned());
        proposed.extend(after.iter().cloned());
        let mut candidate = Vec::new();
        candidate.try_reserve_exact(new_len).map_err(|_| EditError::OutOfMemory)?;
        for piece in &proposed {
            let piece_end = piece.start.checked_add(piece.len).ok_or(EditError::Limit)?;
            candidate.extend_from_slice(piece.data.get(piece.start..piece_end).ok_or(EditError::InvalidOperation)?);
        }
        if candidate.len() != new_len { return Err(EditError::InvalidOperation); }
        let cache = Arc::new(candidate);
        let model = match parse_owned_document(&cache) {
            Ok(model) => model,
            Err(error) => { let (mapped, diagnostic) = map_parse_error(error); self.diagnostic = diagnostic; return Err(mapped); }
        };
        let tokens = match parse_tokens(&cache) { Ok(tokens) => tokens, Err((error, diagnostic)) => { self.diagnostic = diagnostic; return Err(error); } };
        let mut removed = Vec::new();
        if remove_len > 0 { removed.try_reserve_exact(1).map_err(|_| EditError::OutOfMemory)?; removed.push(Piece { data: Arc::new(removed_bytes), start: 0, len: remove_len }); }
        let cost = removed_charge.checked_add(insert.len()).ok_or(EditError::Limit)?;
        if cost > self.limits.history_bytes { return Err(EditError::HistoryLimit); }
        let state = self.next_state;
        if label.is_empty() || label.len() >= HISTORY_LABEL_CAPACITY { return Err(EditError::InvalidArgument); }
        let coalesce = coalescible && self.cursor == self.history.len() && self.saved_state != self.state_id
            && self.history.last().is_some_and(|c| c.coalescible && c.target_slot == target_slot && c.offset == offset);
        let mut history_label = String::new();
        history_label.try_reserve_exact(label.len()).map_err(|_| EditError::OutOfMemory)?;
        history_label.push_str(label);
        let mut projected_bytes = self.history.iter().take(self.cursor).try_fold(0usize, |sum, c| sum.checked_add(command_cost(c)).ok_or(EditError::Limit))?;
        let preallocation_charge = if coalesce { insert.len() } else { cost };
        if self.history_bytes.checked_add(preallocation_charge).is_none_or(|sum| sum > self.limits.history_bytes) { return Err(EditError::HistoryLimit); }
        if coalesce { projected_bytes = projected_bytes.checked_sub(command_cost(self.history.last().ok_or(EditError::InvalidOperation)?)).ok_or(EditError::InvalidOperation)?; }
        if !coalesce && self.history.len() < self.limits.history_commands && self.history.capacity() <= self.history.len() {
            self.history.try_reserve(1).map_err(|_| EditError::OutOfMemory)?;
        }
        let mut command = Command { offset, removed, inserted, before_state: self.state_id, after_state: state,
            label: history_label, target_slot, coalescible };
        if coalesce {
            let prior = self.history.pop().ok_or(EditError::InvalidOperation)?;
            command.before_state = prior.before_state;
            command.removed = prior.removed;
            command.label = prior.label;
        }
        self.history.truncate(self.cursor);
        self.history_bytes = projected_bytes;
        let actual_cost = command_cost(&command);
        while self.history.len() >= self.limits.history_commands {
            if self.history.is_empty() { return Err(EditError::HistoryLimit); }
            let first = self.history.remove(0);
            self.history_bytes = self.history_bytes.saturating_sub(command_cost(&first));
            self.cursor = self.cursor.saturating_sub(1);
            if self.saved_state == first.before_state { self.saved_state = 0; }
        }
        self.history.push(command);
        self.history_bytes = self.history_bytes.checked_add(actual_cost).ok_or(EditError::Limit)?;
        self.cursor = self.history.len();
        self.pieces = proposed;
        self.byte_len = new_len;
        self.state_id = state;
        self.next_state += 1;
        self.cached_source = cache;
        self.model = model;
        self.tokens = tokens;
        self.diagnostic = XmlDiagnostic::default();
        Ok(())
    }

    pub fn undo(&mut self) -> Result<(), EditError> {
        if self.cursor == 0 { return Err(EditError::InvalidOperation); }
        let command = self.history.get(self.cursor - 1).cloned().ok_or(EditError::InvalidOperation)?;
        self.apply_history(&command, false)?;
        self.state_id = command.before_state;
        self.cursor -= 1;
        Ok(())
    }
    pub fn redo(&mut self) -> Result<(), EditError> {
        let command = self.history.get(self.cursor).cloned().ok_or(EditError::InvalidOperation)?;
        self.apply_history(&command, true)?;
        self.state_id = command.after_state;
        self.cursor += 1;
        Ok(())
    }
    fn apply_history(&mut self, command: &Command, forward: bool) -> Result<(), EditError> {
        let (remove, add) = if forward { (&command.removed, &command.inserted) } else { (&command.inserted, &command.removed) };
        let remove_len = piece_bytes(remove)?;
        self.replace_history_raw(command.offset, remove_len, add)?;
        Ok(())
    }
    fn replace_history_raw(&mut self, offset: usize, remove: usize, insert: &[Piece]) -> Result<(), EditError> {
        let insert_len = piece_bytes(insert)?;
        let mut after = Vec::new();
        let mut before = Vec::new();
        before.try_reserve(self.pieces.len()).map_err(|_| EditError::OutOfMemory)?;
        after.try_reserve(self.pieces.len()).map_err(|_| EditError::OutOfMemory)?;
        let mut cursor = 0usize;
        let end = offset.checked_add(remove).ok_or(EditError::Limit)?;
        if end > self.byte_len { return Err(EditError::InvalidOperation); }
        for piece in &self.pieces {
            let piece_end = cursor.checked_add(piece.len).ok_or(EditError::Limit)?;
            if cursor < offset {
                let keep = offset.min(piece_end) - cursor;
                if keep > 0 { before.push(piece.slice(0, keep).ok_or(EditError::InvalidOperation)?); }
            }
            if piece_end > end {
                let suffix_at = end.saturating_sub(cursor).min(piece.len);
                if suffix_at < piece.len { after.push(piece.slice(suffix_at, piece.len - suffix_at).ok_or(EditError::InvalidOperation)?); }
            }
            cursor = piece_end;
        }
        if end > cursor || cursor < offset { return Err(EditError::InvalidOperation); }
        let count = before.len().checked_add(insert.len()).and_then(|n| n.checked_add(after.len())).ok_or(EditError::Limit)?;
        if count > MAX_PIECES { return Err(EditError::Limit); }
        let mut pieces = Vec::new(); pieces.try_reserve_exact(count).map_err(|_| EditError::OutOfMemory)?;
        pieces.extend(before); pieces.extend(insert.iter().cloned()); pieces.extend(after);
        let new_len = self.byte_len.checked_sub(remove).and_then(|n| n.checked_add(insert_len)).ok_or(EditError::Limit)?;
        let mut bytes = Vec::new(); bytes.try_reserve_exact(new_len).map_err(|_| EditError::OutOfMemory)?;
        for piece in &pieces { bytes.extend_from_slice(piece.data.get(piece.start..piece.start.checked_add(piece.len).ok_or(EditError::Limit)?).ok_or(EditError::InvalidOperation)?); }
        if bytes.len() != new_len { return Err(EditError::InvalidOperation); }
        let cache = Arc::new(bytes);
        let model = parse_owned_document(&cache).map_err(|e| map_parse_error(e).0)?;
        let tokens = parse_tokens(&cache).map_err(|e| e.0)?;
        self.pieces = pieces;
        self.byte_len = cache.len(); self.cached_source = cache; self.model = model; self.tokens = tokens;
        Ok(())
    }
}

fn command_cost(command: &Command) -> usize { piece_bytes(&command.removed).unwrap_or(usize::MAX).saturating_add(piece_bytes(&command.inserted).unwrap_or(usize::MAX)) }
fn piece_bytes(pieces: &[Piece]) -> Result<usize, EditError> { pieces.iter().try_fold(0usize, |sum, p| sum.checked_add(p.len).ok_or(EditError::Limit)) }
fn map_parse_error(error: OwnedParseError) -> (EditError, XmlDiagnostic) {
    match error {
        OwnedParseError::Parse(DocumentParseError { error, diagnostic }) => {
            use vexel_document::DocumentError;
            let mapped = match error { DocumentError::Limit | DocumentError::ResourceExhausted => EditError::Limit,
                DocumentError::Parse => EditError::MalformedXml, DocumentError::OutOfMemory | DocumentError::IdExhausted => EditError::OutOfMemory,
                DocumentError::InvalidArgument => EditError::InvalidArgument };
            (mapped, diagnostic)
        },
        OwnedParseError::Canceled { .. } => (EditError::InvalidOperation, XmlDiagnostic::default()),
    }
}

pub(crate) fn parse_tokens(source: &[u8]) -> Result<Vec<XmlToken>, (EditError, XmlDiagnostic)> {
    let capacity = (64 * 1024 * 1024) / std::mem::size_of::<XmlToken>();
    let (tokens, parsed) = tokenize_with_capacity(source, XmlLimits::default(), capacity);
    if parsed.diagnostic.category != XmlError::None {
        let error = match parsed.diagnostic.category {
            XmlError::InputLimit | XmlError::NodeLimit | XmlError::DepthLimit | XmlError::AttributeLimit | XmlError::TextLimit => EditError::Limit,
            XmlError::OutputExhausted => EditError::Limit,
            _ => EditError::MalformedXml,
        };
        return Err((error, parsed.diagnostic));
    }
    Ok(tokens)
}
use crate::{EditError, Editor};

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct HistoryEntry { pub label: String, pub state_cursor: usize, pub is_current: bool, pub is_saved: bool }

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct HistoryState { pub count: usize, pub cursor: usize, pub saved_cursor: Option<usize> }

impl Editor {
    pub fn history_state(&self) -> HistoryState {
        let saved_cursor = if self.saved_state == self.history.first().map_or(self.state_id, |c| c.before_state) {
            Some(0)
        } else { self.history.iter().position(|c| c.after_state == self.saved_state).map(|i| i + 1) };
        HistoryState { count: self.history.len(), cursor: self.cursor, saved_cursor }
    }
    pub fn history_entry(&self, index: usize) -> Option<HistoryEntry> {
        let command = self.history.get(index)?;
        Some(HistoryEntry { label: command.label.clone(), state_cursor: index + 1,
            is_current: self.cursor == index + 1, is_saved: command.after_state == self.saved_state })
    }
    pub fn history_saved_cursor(&self) -> Option<usize> { self.history_state().saved_cursor }
    pub fn history_jump(&mut self, state_cursor: usize) -> Result<(), EditError> {
        if state_cursor > self.history.len() { return Err(EditError::InvalidArgument); }
        while self.cursor > state_cursor { self.undo()?; }
        while self.cursor < state_cursor { self.redo()?; }
        Ok(())
    }
}
use crate::{EditError, Editor};
use vexel_document::{DocumentHandle, DocumentSourceSpan};
use vexel_xml::TokenKind;

pub type SourceSpan = DocumentSourceSpan;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Attribute { pub name: SourceSpan, pub value: SourceSpan, pub quote: u8 }

impl Editor {
    pub fn root(&self) -> Option<DocumentHandle> { self.model.root() }
    pub fn find_id(&self, id: &[u8]) -> Option<DocumentHandle> {
        self.try_find_id(id).ok().flatten()
    }
    pub fn try_find_id(&self, id: &[u8]) -> Result<Option<DocumentHandle>, EditError> {
        for slot in 0..self.model.node_count() {
            let Some(handle) = self.model.node_at(slot) else { continue; };
            for index in 0..self.model.attribute_count(handle) {
                let (name, value) = self.model.attribute_at(handle, index).ok_or(EditError::InvalidOperation)?;
                if name != b"id" { continue; }
                let mut decoded = Vec::new(); decoded.try_reserve(value.len()).map_err(|_| EditError::OutOfMemory)?;
                decode_entities(value, &mut decoded)?;
                if decoded == id { return Ok(Some(handle)); }
            }
        }
        Ok(None)
    }
    pub fn element_at_offset(&self, offset: usize) -> Option<DocumentHandle> {
        if offset >= self.cached_source.len() { return None; }
        let mut best: Option<(usize, DocumentHandle)> = None;
        for slot in 0..self.model.node_count() {
            let handle = self.model.node_at(slot)?;
            let span = self.model.source_span(handle)?;
            if offset >= span.offset && offset.checked_sub(span.offset)? < span.length {
                let depth = self.model.depth(handle)?;
                if best.is_none_or(|(current, _)| depth > current) { best = Some((depth, handle)); }
            }
        }
        best.map(|(_, handle)| handle)
    }
    pub fn tag_name(&self, handle: DocumentHandle) -> Option<&[u8]> { self.model.tag_name(handle) }
    pub fn source_span(&self, handle: DocumentHandle) -> Option<SourceSpan> { self.model.source_span(handle) }
    pub fn attribute_count(&self, handle: DocumentHandle) -> usize { self.model.attribute_count(handle) }
    pub fn attribute_at(&self, handle: DocumentHandle, index: usize) -> Option<Attribute> {
        if index >= self.model.attribute_count(handle) { return None; }
        let element = self.model.source_span(handle)?;
        let mut in_element = false;
        let mut seen = 0usize;
        for token in &self.tokens {
            if matches!(token.kind, TokenKind::StartElement | TokenKind::EmptyElement) && token.source.offset == element.offset { in_element = true; continue; }
            if in_element && token.kind == TokenKind::Attribute {
                if seen == index {
                    let quote = *self.cached_source.get(token.value.offset.checked_sub(1)?)?;
                    return Some(Attribute { name: SourceSpan { offset: token.name.offset, length: token.name.length },
                        value: SourceSpan { offset: token.value.offset, length: token.value.length }, quote });
                }
                seen += 1;
            } else if in_element { break; }
        }
        None
    }
    pub fn span_bytes(&self, span: SourceSpan) -> Option<&[u8]> {
        self.cached_source.get(span.offset..span.offset.checked_add(span.length)?)
    }
    pub fn materialize_span(&self, span: SourceSpan, output: &mut [u8]) -> Result<usize, EditError> {
        let bytes = self.span_bytes(span).ok_or(EditError::InvalidArgument)?;
        if output.len() < bytes.len() { return Err(EditError::InvalidArgument); }
        output[..bytes.len()].copy_from_slice(bytes); Ok(bytes.len())
    }
    pub fn decoded_span(&self, span: SourceSpan, output: &mut [u8]) -> Result<usize, EditError> {
        let bytes = self.span_bytes(span).ok_or(EditError::InvalidArgument)?;
        let mut decoded = Vec::new(); decoded.try_reserve(bytes.len()).map_err(|_| EditError::OutOfMemory)?;
        decode_entities(bytes, &mut decoded)?;
        if output.len() < decoded.len() { return Err(EditError::InvalidArgument); }
        output[..decoded.len()].copy_from_slice(&decoded); Ok(decoded.len())
    }
    pub fn text_content(&self, handle: DocumentHandle, output: &mut [u8]) -> Result<usize, EditError> {
        let node = self.model.source_span(handle).ok_or(EditError::StaleHandle)?;
        let end = node.offset.checked_add(node.length).ok_or(EditError::Limit)?;
        let mut decoded = Vec::new();
        for token in self.tokens.iter().filter(|t| matches!(t.kind, TokenKind::Text | TokenKind::Cdata)
            && t.source.offset >= node.offset && t.source.offset < end) {
            let value = token.value.slice(&self.cached_source).ok_or(EditError::InvalidOperation)?;
            let extra = if token.kind == TokenKind::Cdata { value.len() } else { value.len() };
            decoded.try_reserve(extra).map_err(|_| EditError::OutOfMemory)?;
            if token.kind == TokenKind::Cdata { decoded.extend_from_slice(value); }
            else { decode_entities(value, &mut decoded)?; }
        }
        if output.len() < decoded.len() { return Err(EditError::InvalidArgument); }
        output[..decoded.len()].copy_from_slice(&decoded); Ok(decoded.len())
    }
    pub fn element_path(&self, handle: DocumentHandle, output: &mut [u8]) -> Result<usize, EditError> {
        let mut chain = Vec::new(); let mut current = handle;
        loop {
            if chain.len() >= 256 { return Err(EditError::Limit); }
            self.model.tag_name(current).ok_or(EditError::StaleHandle)?;
            chain.push(current);
            let Some(parent) = self.model.parent(current) else { break; };
            current = parent;
        }
        let mut path = Vec::new();
        for node in chain.iter().rev() {
            let name = self.model.tag_name(*node).ok_or(EditError::StaleHandle)?;
            let mut ordinal = 1usize;
            if let Some(parent) = self.model.parent(*node) {
                let mut sibling = self.model.first_child(parent);
                while let Some(s) = sibling {
                    if s == *node { break; }
                    if self.model.tag_name(s) == Some(name) { ordinal += 1; }
                    sibling = self.model.next_sibling(s);
                }
            }
            path.try_reserve(name.len().saturating_add(24)).map_err(|_| EditError::OutOfMemory)?;
            path.push(b'/'); path.extend_from_slice(name); path.push(b'[');
            path.extend_from_slice(ordinal.to_string().as_bytes()); path.push(b']');
        }
        if output.len() < path.len() { return Err(EditError::InvalidArgument); }
        output[..path.len()].copy_from_slice(&path); Ok(path.len())
    }
}

pub(crate) fn decode_entities(raw: &[u8], out: &mut Vec<u8>) -> Result<(), EditError> {
    let mut at = 0usize;
    while at < raw.len() {
        if raw[at] != b'&' { out.push(raw[at]); at += 1; continue; }
        let start = at + 1;
        let rel = raw.get(start..).and_then(|tail| tail.iter().position(|b| *b == b';')).ok_or(EditError::MalformedXml)?;
        let end = start.checked_add(rel).ok_or(EditError::Limit)?;
        let entity = raw.get(start..end).ok_or(EditError::MalformedXml)?;
        match entity {
            b"amp" => out.push(b'&'), b"lt" => out.push(b'<'), b"gt" => out.push(b'>'),
            b"quot" => out.push(b'"'), b"apos" => out.push(b'\''),
            value if value.starts_with(b"#") => {
                let (radix, digits) = if value.get(1) == Some(&b'x') || value.get(1) == Some(&b'X') { (16, &value[2..]) } else { (10, &value[1..]) };
                let text = std::str::from_utf8(digits).map_err(|_| EditError::MalformedXml)?;
                let cp = u32::from_str_radix(text, radix).map_err(|_| EditError::MalformedXml)?;
                let c = char::from_u32(cp).filter(|c| vexel_xml::is_xml_char(*c as u32)).ok_or(EditError::MalformedXml)?;
                let mut buf = [0; 4]; out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
            }
            _ => return Err(EditError::MalformedXml),
        }
        at = end.checked_add(1).ok_or(EditError::Limit)?;
    }
    Ok(())
}

#include "document_edit_internal.h"

#include <stdlib.h>
#include <string.h>

#define DOCUMENT_EDIT_MAX_PIECES 1000000U

static void release_pieces(document_edit *edit, document_edit_piece *pieces,
                           size_t count)
{
    for (size_t i = 0U; i < count; ++i)
        document_edit_blob_release(edit, pieces[i].blob);
    free(pieces);
}

void document_edit_blob_retain(document_edit_blob *blob)
{
    if (blob != NULL) ++blob->references;
}

void document_edit_blob_release(document_edit *edit, document_edit_blob *blob)
{
    if (blob == NULL) return;
    if (blob->references > 1U) {
        --blob->references;
        return;
    }
    if (edit != NULL && edit->blob_bytes >= blob->length)
        edit->blob_bytes -= blob->length;
    free(blob->bytes);
    free(blob);
}

document_edit_blob *document_edit_blob_create(document_edit *edit,
    const uint8_t *bytes, size_t length, document_edit_error *out_error)
{
    if (out_error != NULL) *out_error = DOCUMENT_EDIT_INVALID_ARGUMENT;
    if (edit == NULL || (length > 0U && bytes == NULL)) return NULL;
    if (length == 0U) {
        if (out_error != NULL) *out_error = DOCUMENT_EDIT_OK;
        return NULL;
    }
    if (length > edit->limits.history_bytes ||
        edit->blob_bytes > edit->limits.history_bytes - length) {
        if (out_error != NULL) *out_error = DOCUMENT_EDIT_HISTORY_LIMIT;
        return NULL;
    }
    document_edit_blob *blob = calloc(1U, sizeof(*blob));
    if (blob == NULL) {
        if (out_error != NULL) *out_error = DOCUMENT_EDIT_OUT_OF_MEMORY;
        return NULL;
    }
    blob->bytes = malloc(length);
    if (blob->bytes == NULL) {
        free(blob);
        if (out_error != NULL) *out_error = DOCUMENT_EDIT_OUT_OF_MEMORY;
        return NULL;
    }
    memcpy(blob->bytes, bytes, length);
    blob->length = length;
    blob->references = 1U;
    edit->blob_bytes += length;
    if (out_error != NULL) *out_error = DOCUMENT_EDIT_OK;
    return blob;
}

static bool piece_bytes(const document_edit *edit, const document_edit_piece *piece,
                        const uint8_t **out_bytes)
{
    if (edit == NULL || piece == NULL || out_bytes == NULL) return false;
    if (piece->blob == NULL) {
        if (piece->offset > edit->original.len ||
            piece->length > edit->original.len - piece->offset) return false;
        *out_bytes = edit->original.ptr + piece->offset;
    } else {
        if (piece->offset > piece->blob->length ||
            piece->length > piece->blob->length - piece->offset) return false;
        *out_bytes = piece->blob->bytes + piece->offset;
    }
    return true;
}

bool document_edit_read_range(const document_edit *edit, size_t offset,
                              size_t length, uint8_t *output)
{
    if (edit == NULL || (length > 0U && output == NULL) || offset > edit->byte_length ||
        length > edit->byte_length - offset) return false;
    size_t output_offset = 0U;
    size_t cursor = 0U;
    size_t end = offset + length;
    for (size_t i = 0U; i < edit->piece_count && output_offset < length; ++i) {
        const document_edit_piece *piece = &edit->pieces[i];
        size_t piece_end;
        if (!base_size_add(cursor, piece->length, &piece_end)) return false;
        if (piece_end > offset && cursor < end) {
            size_t take_start = cursor < offset ? offset - cursor : 0U;
            size_t take_end = piece_end > end ? end - cursor : piece->length;
            size_t take = take_end - take_start;
            const uint8_t *bytes = NULL;
            if (!piece_bytes(edit, piece, &bytes)) return false;
            memcpy(output + output_offset, bytes + take_start, take);
            output_offset += take;
        }
        cursor = piece_end;
    }
    return output_offset == length;
}

static bool append_piece(document_edit_piece *pieces, size_t capacity, size_t *count,
                         size_t offset, size_t length, document_edit_blob *blob)
{
    if (length == 0U) return true;
    if (*count > 0U) {
        document_edit_piece *last = &pieces[*count - 1U];
        size_t last_end;
        if (last->blob == blob && base_size_add(last->offset, last->length, &last_end) &&
            last_end == offset) {
            return base_size_add(last->length, length, &last->length);
        }
    }
    if (*count >= capacity) return false;
    pieces[*count] = (document_edit_piece){offset, length, blob};
    document_edit_blob_retain(blob);
    ++*count;
    return true;
}

static bool append_range(const document_edit *edit, document_edit_piece *output,
                         size_t capacity, size_t *count, size_t start, size_t end)
{
    if (start > end || end > edit->byte_length) return false;
    size_t cursor = 0U;
    for (size_t i = 0U; i < edit->piece_count && cursor < end; ++i) {
        const document_edit_piece *piece = &edit->pieces[i];
        size_t piece_end;
        if (!base_size_add(cursor, piece->length, &piece_end)) return false;
        if (piece_end > start && cursor < end) {
            size_t within = cursor < start ? start - cursor : 0U;
            size_t take_end = piece_end > end ? end - cursor : piece->length;
            if (!append_piece(output, capacity, count, piece->offset + within,
                              take_end - within, piece->blob)) return false;
        }
        cursor = piece_end;
    }
    return start == end || cursor >= end;
}

static bool piece_table_replace_copy(document_edit *edit, size_t offset,
                                     size_t remove_length, document_edit_blob *insert,
                                     document_edit_piece **out_pieces,
                                     size_t *out_count, size_t *out_capacity,
                                     size_t *out_length)
{
    if (offset > edit->byte_length || remove_length > edit->byte_length - offset)
        return false;
    size_t inserted_length = insert == NULL ? 0U : insert->length;
    size_t new_length = edit->byte_length - remove_length;
    if (!base_size_add(new_length, inserted_length, &new_length)) return false;
    size_t capacity;
    if (!base_size_add(edit->piece_count, 3U, &capacity) ||
        capacity > DOCUMENT_EDIT_MAX_PIECES) return false;
    document_edit_piece *pieces = calloc(capacity, sizeof(*pieces));
    if (pieces == NULL) return false;
    size_t count = 0U;
    bool ok = append_range(edit, pieces, capacity, &count, 0U, offset);
    if (ok && insert != NULL)
        ok = append_piece(pieces, capacity, &count, 0U, inserted_length, insert);
    size_t rest_start = offset + remove_length;
    if (ok) ok = append_range(edit, pieces, capacity, &count, rest_start,
                              edit->byte_length);
    if (!ok || count > DOCUMENT_EDIT_MAX_PIECES) {
        release_pieces(edit, pieces, count);
        return false;
    }
    *out_pieces = pieces;
    *out_count = count;
    *out_capacity = capacity;
    *out_length = new_length;
    return true;
}

bool document_edit_replace_raw(document_edit *edit, size_t offset, size_t remove_length,
                               document_edit_blob *insert)
{
    if (edit == NULL) return false;
    document_edit_piece *pieces = NULL;
    size_t count = 0U, capacity = 0U, length = 0U;
    if (!piece_table_replace_copy(edit, offset, remove_length, insert, &pieces,
                                   &count, &capacity, &length)) return false;
    release_pieces(edit, edit->pieces, edit->piece_count);
    edit->pieces = pieces;
    edit->piece_count = count;
    edit->piece_capacity = capacity;
    edit->byte_length = length;
    return true;
}

static void command_release(document_edit *edit, document_edit_command *command)
{
    document_edit_blob_release(edit, command->before);
    document_edit_blob_release(edit, command->after);
    memset(command, 0, sizeof(*command));
}

static void clear_redo(document_edit *edit)
{
    for (size_t i = edit->command_cursor; i < edit->command_count; ++i)
        command_release(edit, &edit->commands[i]);
    edit->command_count = edit->command_cursor;
}

static bool reserve_commands(document_edit *edit)
{
    if (edit->command_count < edit->command_capacity) return true;
    if (edit->command_count == edit->limits.history_commands &&
        edit->command_capacity == edit->limits.history_commands) return true;
    size_t next = edit->command_capacity == 0U ? 8U : edit->command_capacity * 2U;
    if (next > edit->limits.history_commands) next = edit->limits.history_commands;
    if (next <= edit->command_capacity || next > SIZE_MAX / sizeof(*edit->commands))
        return false;
    document_edit_command *commands = realloc(edit->commands,
                                               next * sizeof(*edit->commands));
    if (commands == NULL) return false;
    memset(commands + edit->command_capacity, 0,
           (next - edit->command_capacity) * sizeof(*commands));
    edit->commands = commands;
    edit->command_capacity = next;
    return true;
}

static void drop_oldest_command(document_edit *edit)
{
    if (edit->command_count == 0U) return;
    command_release(edit, &edit->commands[0]);
    if (edit->command_count > 1U)
        memmove(edit->commands, edit->commands + 1U,
                (edit->command_count - 1U) * sizeof(*edit->commands));
    --edit->command_count;
    if (edit->command_cursor > 0U) --edit->command_cursor;
    memset(&edit->commands[edit->command_count], 0, sizeof(*edit->commands));
}

static bool make_piece_copy(document_edit *edit, size_t offset, size_t length,
                            uint8_t **out_bytes)
{
    uint8_t *bytes = length == 0U ? NULL : malloc(length);
    if (length > 0U && bytes == NULL) return false;
    if (length > 0U && !document_edit_read_range(edit, offset, length, bytes)) {
        free(bytes);
        return false;
    }
    *out_bytes = bytes;
    return true;
}

document_edit_error document_edit_commit_replace(document_edit *edit,
    size_t offset, size_t remove_length, const uint8_t *insert, size_t insert_length,
    uint32_t target_slot, bool coalescible_attribute,
    document_edit_history_action action)
{
    base_bytes label = document_edit_history_action_label(action);
    if (edit == NULL || (insert_length > 0U && insert == NULL) ||
        !base_bytes_valid(label) || label.len == 0U ||
        label.len >= DOCUMENT_EDIT_HISTORY_LABEL_CAP ||
        offset > edit->byte_length || remove_length > edit->byte_length - offset)
        return DOCUMENT_EDIT_INVALID_ARGUMENT;
    size_t next_length = edit->byte_length - remove_length;
    svg_xml_options xml_options = svg_xml_default_options();
    if (!base_size_add(next_length, insert_length, &next_length) ||
        next_length > xml_options.limits.input_bytes) return DOCUMENT_EDIT_LIMIT;
    if (edit->next_state_id == UINT64_MAX) return DOCUMENT_EDIT_LIMIT;
    if (remove_length == insert_length) {
        uint8_t *existing = NULL;
        if (!make_piece_copy(edit, offset, remove_length, &existing))
            return DOCUMENT_EDIT_OUT_OF_MEMORY;
        bool same = remove_length == 0U || memcmp(existing, insert, remove_length) == 0;
        free(existing);
        if (same) return DOCUMENT_EDIT_OK;
    }

    bool coalesce = coalescible_attribute && edit->command_cursor == edit->command_count &&
        edit->command_count > 0U &&
        edit->saved_state_id != edit->state_id &&
        edit->commands[edit->command_count - 1U].coalescible_attribute &&
        edit->commands[edit->command_count - 1U].target_slot == target_slot &&
        edit->commands[edit->command_count - 1U].offset == offset;
    uint8_t *before_bytes = NULL;
    if (!make_piece_copy(edit, offset, remove_length, &before_bytes))
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    document_edit_error blob_error = DOCUMENT_EDIT_OK;
    document_edit_blob *before = coalesce ? NULL : document_edit_blob_create(
        edit, before_bytes, remove_length, &blob_error);
    free(before_bytes);
    if (!coalesce && remove_length > 0U && before == NULL) return blob_error;
    document_edit_blob *after = document_edit_blob_create(edit, insert, insert_length,
                                                          &blob_error);
    if (insert_length > 0U && after == NULL) {
        document_edit_blob_release(edit, before);
        return blob_error;
    }

    document_edit_piece *pieces = NULL;
    size_t piece_count = 0U, piece_capacity = 0U, byte_length = 0U;
    if (!piece_table_replace_copy(edit, offset, remove_length, after, &pieces,
                                  &piece_count, &piece_capacity, &byte_length)) {
        document_edit_blob_release(edit, before);
        document_edit_blob_release(edit, after);
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    }
    if (!coalesce && edit->command_count < edit->limits.history_commands &&
        !reserve_commands(edit)) {
        release_pieces(edit, pieces, piece_count);
        document_edit_blob_release(edit, before);
        document_edit_blob_release(edit, after);
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    }

    clear_redo(edit);
    uint64_t new_state = edit->next_state_id++;
    if (coalesce) {
        document_edit_command *previous = &edit->commands[edit->command_count - 1U];
        document_edit_blob_release(edit, previous->after);
        previous->after = after;
        previous->after_state = new_state;
        memcpy(previous->label, label.ptr, label.len);
        previous->label[label.len] = '\0';
    } else {
        if (edit->command_count == edit->limits.history_commands) drop_oldest_command(edit);
        document_edit_command command = {.offset = offset, .before = before,
            .after = after, .target_slot = target_slot,
            .coalescible_attribute = coalescible_attribute,
            .before_state = edit->state_id, .after_state = new_state};
        memcpy(command.label, label.ptr, label.len);
        command.label[label.len] = '\0';
        edit->commands[edit->command_count++] = command;
        edit->command_cursor = edit->command_count;
    }
    release_pieces(edit, edit->pieces, edit->piece_count);
    edit->pieces = pieces;
    edit->piece_count = piece_count;
    edit->piece_capacity = piece_capacity;
    edit->byte_length = byte_length;
    edit->state_id = new_state;
    document_edit_invalidate_index(edit);
    return DOCUMENT_EDIT_OK;
}

document_edit_error document_edit_undo(document_edit *edit)
{
    if (edit == NULL) return DOCUMENT_EDIT_INVALID_ARGUMENT;
    if (edit->command_cursor == 0U) return DOCUMENT_EDIT_INVALID_OPERATION;
    document_edit_command *command = &edit->commands[edit->command_cursor - 1U];
    size_t after_length = command->after == NULL ? 0U : command->after->length;
    size_t before_length = command->before == NULL ? 0U : command->before->length;
    if (!document_edit_validate_replace(edit, 0U, edit->byte_length,
            command->offset, after_length,
            command->before == NULL ? NULL : command->before->bytes,
            before_length, false, false)) return DOCUMENT_EDIT_MALFORMED_XML;
    if (!document_edit_replace_raw(edit, command->offset, after_length, command->before))
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    --edit->command_cursor;
    edit->state_id = command->before_state;
    document_edit_invalidate_index(edit);
    return DOCUMENT_EDIT_OK;
}

document_edit_error document_edit_redo(document_edit *edit)
{
    if (edit == NULL) return DOCUMENT_EDIT_INVALID_ARGUMENT;
    if (edit->command_cursor >= edit->command_count) return DOCUMENT_EDIT_INVALID_OPERATION;
    document_edit_command *command = &edit->commands[edit->command_cursor];
    size_t before_length = command->before == NULL ? 0U : command->before->length;
    size_t after_length = command->after == NULL ? 0U : command->after->length;
    if (!document_edit_validate_replace(edit, 0U, edit->byte_length,
            command->offset, before_length,
            command->after == NULL ? NULL : command->after->bytes,
            after_length, false, false)) return DOCUMENT_EDIT_MALFORMED_XML;
    if (!document_edit_replace_raw(edit, command->offset, before_length, command->after))
        return DOCUMENT_EDIT_OUT_OF_MEMORY;
    ++edit->command_cursor;
    edit->state_id = command->after_state;
    document_edit_invalidate_index(edit);
    return DOCUMENT_EDIT_OK;
}

