/// Safe observation and fault gates for source saving.
///
/// Returning success permits the native adapter operation to proceed; these
/// hooks cannot supply successful writes, syncs, closes, renames, or publishes.
pub trait SourceSaveHooks {
    fn before_write(&mut self, _file: &File, remaining: &[u8]) -> io::Result<usize> {
        Ok(remaining.len())
    }
    fn before_sync_file(&mut self, _file: &File) -> io::Result<()> { Ok(()) }
    fn before_close(&mut self, _file: &File) -> io::Result<()> { Ok(()) }
    fn before_rename(&mut self, _from: &Path, _to: &Path) -> io::Result<()> { Ok(()) }
    fn before_publish(&mut self, _temporary: &Path, _target: &Path) -> io::Result<()> { Ok(()) }
    fn before_remove_temporary(&mut self, _temporary: &Path) -> io::Result<()> { Ok(()) }
    fn before_sync_directory(&mut self, _directory: &Path) -> io::Result<()> { Ok(()) }
}

/// Owned bounded tokenizer output. Token spans are valid only as long as the
