#[derive(Clone, Debug)]
pub struct EditSnapshot { pieces: Vec<Piece>, byte_len: usize }

impl Editor {
    /// Captures shared immutable buffers and copied descriptors; safe to move
    /// to a worker and independent of later editor changes.
    pub fn snapshot(&self) -> Result<EditSnapshot, EditError> {
        let mut pieces = Vec::new(); pieces.try_reserve_exact(self.pieces.len()).map_err(|_| EditError::OutOfMemory)?;
        pieces.extend(self.pieces.iter().cloned());
        Ok(EditSnapshot { pieces, byte_len: self.byte_len })
    }
}

impl EditSnapshot {
    pub fn byte_length(&self) -> usize { self.byte_len }
    pub fn materialize(&self, output: &mut [u8]) -> Result<usize, EditError> {
        if output.len() < self.byte_len { return Err(EditError::InvalidArgument); }
        let mut used = 0usize;
        for p in &self.pieces {
            let end = p.start.checked_add(p.len).ok_or(EditError::Limit)?;
            let slice = p.data.get(p.start..end).ok_or(EditError::InvalidOperation)?;
            let dest = used.checked_add(slice.len()).ok_or(EditError::Limit)?;
            output.get_mut(used..dest).ok_or(EditError::InvalidArgument)?.copy_from_slice(slice);
            used = dest;
        }
        if used != self.byte_len { return Err(EditError::InvalidOperation); }
        Ok(used)
    }
}

